"""Alternative legal image layouts (direct TYPE3 children, random stages/cells)
used to validate the C++ loader against images it does not itself produce."""
import random

M = (1 << 128) - 1
M64 = (1 << 64) - 1
BMP_NULL = 4194303
OWNS = {0: 16, 16: 64, 64: 128}

def top(v, ln):
    if ln <= 0: return 0
    return (v >> (128 - ln)) << (128 - ln)

def chunk(v, d):
    if d >= 128: return 0
    n = min(6, 128 - d)
    return ((v >> (128 - d - n)) & ((1 << n) - 1)) << (6 - n)

class N:
    def __init__(self, origin, depth, region):
        self.origin, self.depth, self.region = origin, depth, region
        self.locals = []      # (len, hop, value)
        self.children = []    # (key, node)
        self.type = 1
        self.stage = 0
        self.cell = 0
        self.span = 1
        self.bulk_root = False
        self.direct = []      # keys routed as explicit children
        self.bitmap_id = 0
        self.ni_base = 0
        self.bmp = BMP_NULL

def build_node(origin, depth, region, ps):
    n = N(origin, depth, region)
    n.locals_all = ps
    if len(ps) <= 2:
        n.type = 4 if len(ps) == 1 else 5
        n.locals = list(ps)
        return n
    rest = []
    for (ln, hop, v) in ps:
        if ln - depth < 6: n.locals.append((ln, hop, v))
        else: rest.append((ln, hop, v))
    grp = {}
    for (ln, hop, v) in rest:
        grp.setdefault(chunk(v, depth), []).append((ln, hop, v))
    for k in sorted(grp):
        sub = top(region | (((1 << 128) - 1) & 0), 0)  # placeholder
        cregion = region
        # set the 6 bits at [depth, depth+6)
        sh = 128 - depth - 6
        if sh >= 0:
            cregion = (region & ~(((1 << 6) - 1) << sh)) | (k << sh)
        else:
            lo_sh = 128 - depth - 6 + 64
            hb = 64 - depth
            cregion_hi = (region >> 64) | (k >> (6 - hb))
            cregion_lo = (region & M64) | ((k & ((1 << (6 - hb)) - 1)) << (64 - (6 - hb)))
            cregion = (cregion_hi << 64) | cregion_lo
        n.children.append((k, build_node(origin, depth + 6, cregion, grp[k])))
    n.type = 1 if len(n.children) <= 2 else (2 if len(n.children) <= 6 else 3)
    return n

def height(n):
    if not n.children: return 0
    return 1 + max(height(c) for (_, c) in n.children)

def assign_stages(n, parent_stage, rng):
    hi = parent_stage - 1
    lo = height(n)
    n.stage = rng.randint(lo, max(lo, hi))
    for (_, c) in n.children:
        assign_stages(c, n.stage, rng)

def collect(n, out):
    out.append(n)
    for (_, c) in n.children: collect(c, out)

def build_image(prefixes, rng, shuffle_ni=True, direct_children=True):
    """prefixes: list of (len, value128, hop)"""
    f0 = [p for p in prefixes if p[0] <= 16]
    g16 = {}
    g64 = {}
    for (ln, hop, v) in prefixes:
        if 17 <= ln <= 64: g16.setdefault(v >> 48, []).append((ln, hop, v))
        elif ln >= 65: g64.setdefault(v >> 64, []).append((ln, hop, v))
    roots = []
    if f0: roots.append(('root', build_node(0, 0, 0, f0)))
    for k in sorted(g16): roots.append(('f16', k, build_node(16, 16, k << 48, g16[k])))
    for k in sorted(g64): roots.append(('f64', k, build_node(64, 64, k, g64[k])))
    for r in roots:
        node = r[1] if r[0] == 'root' else r[2]
        assign_stages(node, 11, rng)
    nodes = []
    for r in roots:
        collect(r[1] if r[0] == 'root' else r[2], nodes)
    # bulk / direct split and spans
    for n in nodes:
        n.span = 2 if n.type in (2, 3, 5) else 1
        n.direct = []
        n.bulk_keys = []
        if n.type == 3:
            keys = [k for (k, _) in n.children]
            if direct_children:
                k = rng.randint(0, min(3, len(keys) - 4))
                n.direct = sorted(rng.sample(keys, k))
            n.bulk_keys = [k for k in keys if k not in n.direct]
            for (k, c) in n.children:
                if k in n.bulk_keys:
                    c.bulk_root = True
                    c.span = 2
    # placement
    cells = [0] * 11
    by_stage = {s: [n for n in nodes if n.stage == s] for s in range(11)}
    for s in range(11):
        cur = 0
        parents = [n for n in nodes if n.type == 3 and n.bulk_keys
                   and n.children[0][1].stage == s]
        rng.shuffle(parents)
        for p in parents:
            p.bulk_base = cur
            order = sorted(p.bulk_keys)
            for i, k in enumerate(order):
                child = [c for (kk, c) in p.children if kk == k][0]
                child.cell = cur + 2 * i
            cur += 2 * len(order)
        rest2 = [n for n in by_stage[s] if not n.bulk_root and n.span == 2]
        rest1 = [n for n in by_stage[s] if not n.bulk_root and n.span == 1]
        rng.shuffle(rest2); rng.shuffle(rest1)
        lead = 2 * rng.randint(0, len(rest1) // 2) if rest1 else 0
        for n in rest1[:lead]:
            n.cell = cur; cur += 1
        for n in rest2:
            n.cell = cur; cur += 2
        for n in rest1[lead:]:
            n.cell = cur; cur += 1
        cells[s] = cur
    # NI dictionary / vector
    def pattern_of(n):
        p = 0
        for (ln, hop, v) in n.locals:
            l = ln - n.depth
            val = (v >> (128 - n.depth - l)) & ((1 << l) - 1) if l else 0
            p |= 1 << ((1 << l) + val)
        return p
    pats = sorted({pattern_of(n) for n in nodes if n.type <= 3})
    order = [n for n in nodes if n.type <= 3]
    if shuffle_ni: rng.shuffle(order)
    nis = []
    for n in order:
        pat = pattern_of(n)
        n.bitmap_id = pats.index(pat)
        n.ni_base = len(nis) if pat else 0
        if pat:
            lups = []
            for (ln, hop, v) in n.locals:
                l = ln - n.depth
                val = (v >> (128 - n.depth - l)) & ((1 << l) - 1) if l else 0
                lups.append(((1 << l) + val, hop))
            lups.sort()
            nis.extend(h for (_, h) in lups)
    # bmps
    pset = {(ln, v): hop for (ln, hop, v) in prefixes}
    for n in nodes:
        want = None
        for ln in range(n.depth, -1, -1):
            key = (ln, top(n.region, ln))
            if key in pset:
                want = pset[key]; break
        n.bmp = BMP_NULL if want is None else want
    # pack
    banks = [[0] * ((cells[s] + 1) // 2) for s in range(11)]

    def put(rec, off, nb, v):
        for i in range(nb):
            if (v >> i) & 1: rec |= 1 << (off + i)
        return rec

    for n in nodes:
        rec = 0
        rec = put(rec, 0, 3, n.type)
        rec = put(rec, 3, 22, n.bmp)
        if n.type in (4, 5):
            inl = list(n.locals)
            if n.type == 5 and rng.random() < 0.5: inl.reverse()
            for k, (ln, hop, v) in enumerate(inl):
                o = 25 + 94 * k
                if n.origin == 0: frag = (v >> 64) & M64
                elif n.origin == 16: frag = ((v >> 64) << 16) & M64
                else: frag = v & M64
                rec = put(rec, o, 64, frag)
                rec = put(rec, o + 64, 8, ln - n.origin)
                rec = put(rec, o + 72, 22, hop)
        else:
            rec = put(rec, 25, 16, n.bitmap_id)
            rec = put(rec, 41, 22, n.ni_base)
            if n.type == 3:
                bm = 0
                for k in n.bulk_keys: bm |= 1 << k
                rec = put(rec, 63, 64, bm)
                rec = put(rec, 127, 22, n.bulk_base)
                rec = put(rec, 149, 4, n.children[0][1].stage)
                slot = 153
                for k in sorted(n.direct):
                    c = [c for (kk, c) in n.children if kk == k][0]
                    rec = put(rec, slot, 32, (c.cell << 10) | (c.stage << 6) | k)
                    slot += 32
                for _ in range(3 - len(n.direct)):
                    rec = put(rec, slot, 32, 15 << 6)
                    slot += 32
            else:
                slot = 63
                for (k, c) in n.children:
                    rec = put(rec, slot, 32, (c.cell << 10) | (c.stage << 6) | k)
                    slot += 32
                for _ in range((2 if n.type == 1 else 6) - len(n.children)):
                    rec = put(rec, slot, 32, 15 << 6)
                    slot += 32
        row = n.cell >> 1
        if n.span == 2:
            banks[n.stage][row] = rec
        else:
            off = (n.cell & 1) * 128
            banks[n.stage][row] |= rec << off
    img = {'root': None, 'front16': [], 'front64': [], 'cells': cells,
           'banks': [['%064x' % w for w in b] for b in banks],
           'bitmaps': ['%016x' % p for p in pats], 'nexthops': nis}
    for r in roots:
        if r[0] == 'root': img['root'] = [r[1].stage, r[1].cell]
        elif r[0] == 'f16': img['front16'].append(['%04x' % r[1], r[2].stage, r[2].cell])
        else: img['front64'].append(['%016x' % r[1], r[2].stage, r[2].cell])
    return img
